# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A derivative-free (1+1)-Evolution Strategy with adaptive step-size (1/5th success rule).
# Search state: Maintains a single current best candidate point and a global isotropic mutation strength (sigma).
# Candidate generation: New candidates are generated by sampling from a multivariate Gaussian centered at the current best.
# Selection and replacement: Simple elitist replacement; if the new point is better, it replaces the current best.
# Adaptation: The mutation strength sigma is updated every 10 iterations: increased if success rate > 0.2, decreased if < 0.2.
# Exploration mechanisms: Gaussian mutation variance provides global search capabilities controlled by sigma.
# Exploitation mechanisms: The elitist nature focuses search around the best found point, refining accuracy.
# Boundary handling: Candidates generated outside bounds are clipped to the nearest valid value on the constraint surface.
# Budget strategy: Iteratively evaluates candidates until the budget is exhausted.
# Closest known influences: (1+1)-ES, Rechenberg's 1/5th success rule.
# Novelty or unusual aspects: Extremely compact implementation with no dependencies, robust to variable dimensions.
# Failure modes: Susceptible to local optima in highly multi-modal landscapes due to the lack of a diverse population.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'lower') and hasattr(func, 'upper'):
            lb, ub = np.array(func.lower), np.array(func.upper)
        else:
            lb, ub = np.array(func.bounds.lb), np.array(func.bounds.ub)
        
        # Initial sampling
        x = np.random.uniform(lb, ub, self.dim)
        y = func(x)
        evals = 1
        
        # Hyperparameters
        sigma = 0.2 * (ub - lb)
        best_x, best_y = x.copy(), y
        success_count = 0
        
        while evals < self.budget:
            # 1/5th success rule adaptation every 10 iterations
            if evals > 1 and evals % 10 == 0:
                if success_count / 10 > 0.2:
                    sigma *= 1.22
                else:
                    sigma /= 0.82
                success_count = 0

            # Generate candidate
            candidate = best_x + np.random.normal(0, sigma, self.dim)
            candidate = np.clip(candidate, lb, ub)
            
            # Evaluate
            cand_y = func(candidate)
            evals += 1
            
            # Selection
            if cand_y < best_y:
                best_y = cand_y
                best_x = candidate.copy()
                success_count += 1
            
            # Stop if budget reached
            if evals >= self.budget:
                break
                
        return best_x, best_y
